"""Small helpers for a2a-sdk 1.x protobuf messages."""

from __future__ import annotations

from typing import Any, TypeVar

from a2a.types import Part
from google.protobuf.json_format import MessageToDict, ParseDict
from google.protobuf.message import Message
from google.protobuf.struct_pb2 import Struct, Value

ProtoT = TypeVar("ProtoT", bound=Message)

# Metadata key on an agent message that names the token artifact it was streamed
# as. Lets a client skip that artifact's text when it already has the message.
STREAMED_ARTIFACT_ID_METADATA_KEY = "streamed_artifact_id"
# Joins the user-visible utterances of a turn in the terminal status text. A
# client can split on it to tell which utterances it already showed.
TERMINAL_TEXT_SEPARATOR = "\n\n"


def clone_proto(message: ProtoT) -> ProtoT:
    """Return a deep copy of a protobuf message."""
    cloned = type(message)()
    cloned.CopyFrom(message)
    return cloned


def text_part(text: str) -> Part:
    """Build a text ``Part``."""
    return Part(text=text)


def data_part(payload: dict[str, Any]) -> Part:
    """Build a structured-data ``Part`` from a plain dict."""
    return Part(data=ParseDict(payload, Value()))


def message_to_dict(message: Message) -> dict[str, Any]:
    """Serialize a protobuf message with ProtoJSON camelCase names."""
    return MessageToDict(message, preserving_proto_field_name=False)


def as_plain_dict(value: Any) -> dict[str, Any]:
    """Turn protobuf ``Struct`` / ``Value`` metadata into a plain dict."""
    if value is None:
        return {}
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, Struct):
        converted = MessageToDict(value)
        return converted if isinstance(converted, dict) else {}
    if isinstance(value, Message):
        converted = MessageToDict(value)
        return converted if isinstance(converted, dict) else {}
    try:
        return {str(key): item for key, item in dict(value).items()}
    except (TypeError, ValueError):
        return {}


def part_data(part: Part) -> dict[str, Any] | None:
    """Return a data part's payload, or ``None`` when the part is not data."""
    if not part.HasField("data"):
        return None
    converted = MessageToDict(part.data)
    if isinstance(converted, dict):
        return converted
    return None
